// Codegen the chat tool types from the JSON Schema emitted by
// `scripts/export_tool_manifest.py` (which walks every alkera `Tool` subclass).
//
// Two outputs (both committed):
//   - src/generated/toolSchemas.ts  — one TS interface per Pydantic Input/Output model
//   - src/generated/toolManifest.ts — the typed (tool-name → input/output type) index
//                                     + the runtime name list + per-tool metadata
//
// `toolSchemas.ts` is generated by `json-schema-to-typescript`. `toolManifest.ts`
// is a tiny hand-rolled emit driven by the `x-alkera-tools` extension on the
// schema — it is the SHARED SOURCE OF TRUTH for the tool surface: the frontend
// tool-card registry keys off `AlkeraToolName`, so a backend tool rename changes
// this file and fails the drift gate / `tsc` instead of silently degrading.

import { compile } from "json-schema-to-typescript";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, "..");
const REPO = resolve(ROOT, "../..");
const SCHEMA_PATH = resolve(REPO, "packages/shared-openapi/tool-manifest.json");
const OUT_DIR = resolve(ROOT, "src/generated");
const SCHEMAS_PATH = resolve(OUT_DIR, "toolSchemas.ts");
const MANIFEST_PATH = resolve(OUT_DIR, "toolManifest.ts");

const schema = JSON.parse(readFileSync(SCHEMA_PATH, "utf-8"));
mkdirSync(OUT_DIR, { recursive: true });

const banner = `/* eslint-disable */
/**
 * Auto-generated from packages/shared-openapi/tool-manifest.json.
 * Do not edit by hand. Run \`make gen-tool-manifest\` after changing
 * an alkera tool's Input/Output Pydantic models.
 */`;

// json-schema-to-typescript wants a single root schema; surface the $defs.
const wrapped = {
  $schema: schema.$schema,
  title: "AlkeraToolManifest",
  type: "object",
  additionalProperties: false,
  $defs: schema.$defs,
  properties: {},
};

const ts = await compile(wrapped, "AlkeraToolManifest", {
  bannerComment: banner,
  additionalProperties: false,
  unreachableDefinitions: true,
  style: { singleQuote: false, semi: true },
});
writeFileSync(SCHEMAS_PATH, ts, "utf-8");

// json-schema-to-typescript emits one interface per $def, keyed by the $def
// name verbatim (it's already a valid TS identifier, leading underscore and all).
const tsName = (name) => name;

const defNames = Object.keys(schema.$defs).sort();
const typeMapEntries = defNames.map((n) => `  ${tsName(n)}: M.${tsName(n)};`).join("\n");

const tools = schema["x-alkera-tools"];
const toolNames = Object.keys(tools).sort();

const ioEntries = toolNames
  .map(
    (name) =>
      `  ${JSON.stringify(name)}: { input: ${JSON.stringify(tsName(tools[name].input))}; output: ${JSON.stringify(tsName(tools[name].output))} };`,
  )
  .join("\n");

const nameListEntries = toolNames.map((n) => `  ${JSON.stringify(n)},`).join("\n");

const metaEntries = toolNames
  .map(
    (name) =>
      `  ${JSON.stringify(name)}: { title: ${JSON.stringify(tools[name].title)}, app: ${JSON.stringify(tools[name].app)}, hot: ${tools[name].hot} },`,
  )
  .join("\n");

const manifestTs = `/**
 * Auto-generated from packages/shared-openapi/tool-manifest.json.
 * Do not edit by hand. Run \`make gen-tool-manifest\` after changing
 * an alkera tool's Input/Output Pydantic models.
 *
 * The SHARED SOURCE OF TRUTH for the alkera tool surface. \`AlkeraToolName\`
 * is the exhaustive set of tool names the backend exposes; the tool-card
 * registry keys off it, so a backend rename becomes a \`tsc\` error here.
 */

import type * as M from "./toolSchemas";

/** Maps every generated \`$def\` name to its concrete TS type. */
export interface ToolTypeMap {
${typeMapEntries}
}

/** Maps each tool name to its Input/Output type names. */
export interface ToolIOTable {
${ioEntries}
}

export type AlkeraToolName = keyof ToolIOTable;

type Lookup<T extends string> = T extends keyof ToolTypeMap ? ToolTypeMap[T] : never;

export type ToolInput<N extends AlkeraToolName> = Lookup<ToolIOTable[N]["input"]>;
export type ToolOutput<N extends AlkeraToolName> = Lookup<ToolIOTable[N]["output"]>;

/** Runtime list of every alkera tool name (for membership checks). */
export const ALKERA_TOOL_NAMES = [
${nameListEntries}
] as const satisfies readonly AlkeraToolName[];

export interface ToolMeta {
  title: string;
  app: string | null;
  hot: boolean;
}

/** Per-tool advertised metadata (title/app/hot) from the backend spec. */
export const TOOL_META: Record<AlkeraToolName, ToolMeta> = {
${metaEntries}
};
`;

writeFileSync(MANIFEST_PATH, manifestTs, "utf-8");

console.log(
  `✓ wrote ${SCHEMAS_PATH.replace(REPO, ".")} and ${MANIFEST_PATH.replace(REPO, ".")} (${toolNames.length} tools, ${defNames.length} types)`,
);
